files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 650px;
  min-height: 100vh;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #feafe8;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.child {
  box-sizing: border-box;
  width: calc(30% - 60px);
  height: 100%;
  border: 1px solid #000;
  padding-top: 80px;
  padding-left: 20px;
  background-color: #feafe8;
}

.parent {
  display: flex;
  justify-content: center;
  width: 100%;
  height: 200px;
}
